using System.Collections;
using System.Collections.Generic;
using Astrea.GameElements;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SolarLullabyAction", menuName = "Data/Battle/Battle Actions/Sothis/SolarLullaby Action")]
public class SolarLullabyAction : MultipleSoulHeatTierAction
{
	[Header("Solar Lullaby")]
	[SerializeField]
	private float vfxDelay;

	public override DiceActionLogic GetDiceActionLogic(int actionValue = -1)
	{
		if (GetSoulHeatAmountToUse(activateFeedback: false) >= actionValue)
		{
			return diceActionLogic;
		}
		return secondBattleAction.GetDiceActionLogic(actionValue);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		CastMultipleSoulHeatTierFirstActionSoulHeatVariableAction(delegate
		{
			if (IsVFXEnabled())
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(SolarLullabyVFXCoroutine(targets, amount, source));
				ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			}
			else
			{
				CastSolarLullaby(targets, amount, source);
			}
		}, null, null, amount, source);
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		CastMultipleSoulHeatTierFirstActionSoulHeatVariableAction(null, delegate
		{
			secondBattleAction.CastTargetAmount(target, secondActionValue, source);
		}, null, amount, source);
	}

	private void CastSolarLullaby(List<GameObject> targets, int amount, GameObject source)
	{
		battleAction.AreaCastTargetAmount(targets, amount, source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private IEnumerator SolarLullabyVFXCoroutine(List<GameObject> targets, int amount, GameObject source)
	{
		PlaySFX();
		SpawnVFX(5f);
		yield return new WaitForSeconds(vfxDelay);
		CastSolarLullaby(targets, amount, source);
	}
}
